// Keys are generated by the server (`<purpose>/<uuid>.<ext>`). Every driver
// refuses anything else, so a key can never point outside its folder or bucket.
const KEY_PATTERN = /^[a-z]+\/[0-9a-f-]{36}\.[a-z0-9]{1,8}$/;

export const isValidKey = (key) => typeof key === 'string' && KEY_PATTERN.test(key);

export function assertValidKey(key) {
  if (!isValidKey(key)) throw new Error('Invalid storage key');
}
